(function(){
 'use strict';
 const C=window.YoisakiCore,CH=window.YoisakiChart,E=window.YoisakiExport;
 const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
 const fmt=x=>Number(x||0).toLocaleString('zh-CN');
 const date=x=>new Date(x).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'});
 const selected=(v,x)=>String(v)===String(x)?' selected':'';
 const checked=x=>x?' checked':'';
 const cleanName=x=>String(x||'Yoisaki').replace(/[\\/:*?"<>|]/g,'_').slice(0,90);
 let favorites=C.readStorage('yoisaki-favorites',[]).filter(x=>C.cards.has(x));
 let saved=C.readStorage('yoisaki-saved',[]).filter(x=>x&&x.plan&&x.id).slice(0,100);
 let drafts={team:C.emptyPlan(),single:{...C.emptyPlan(),mode:'single'}},mode='team',plan=drafts.team;
 try{const d=C.readStorage('yoisaki-drafts',null);if(d){drafts.team=C.sanitizePlan(d.team);drafts.single=C.sanitizePlan(d.single);mode=d.mode==='single'?'single':'team';plan=drafts[mode];}}catch(_){}
 let currentView='',cardPage=1,cardFilters={query:'',character:'',unit:'',attr:'',rarity:'',favorite:false,sort:'new',supply:''};
 let detail={id:0,trained:false,skillLevel:4,characterRank:1},picker={slot:0,page:1,query:'',character:''},openDisclosures=new Set(['area-options']),lastResult=null;
 const chartState={songId:1,difficulty:'expert',mode:'dynamic',query:'',limit:45,loaded:null,player:null,controller:null,vocalId:null,speed:10,rate:1,offset:0,silent:false,staticDark:true,zoom:100,staticCanvas:null,token:0,seeking:false};
 const storageUnavailable=!C.writeStorage('yoisaki-storage-probe',1);
 function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200);}
 function persist(){drafts[mode]=plan;if(!C.writeStorage('yoisaki-drafts',{...drafts,mode}))toast('浏览器存储空间不足，请导出 JSON 保存方案。',true);}
 function placeholder(){return 'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="600" height="400"><defs><linearGradient id="g"><stop stop-color="#32334b"/><stop offset="1" stop-color="#24283c"/></linearGradient></defs><rect width="600" height="400" fill="url(#g)"/><path d="m290 140 17 40 42 17-42 17-17 40-17-40-42-17 42-17" fill="#998bbf" opacity=".6"/><text x="300" y="300" text-anchor="middle" font-family="sans-serif" font-size="15" fill="#a6a0ba">Yoisaki · 图片暂不可用</text></svg>');}
 document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&!e.target.dataset.failed){const next=window.YoisakiResources.next(e.target.getAttribute('src'));if(next){e.target.src=next;return;}e.target.dataset.failed='1';e.target.src=placeholder();e.target.classList.add('image-failed');e.target.title='图片暂不可用；可运行资源下载器，或在资源设置中启用在线回退。';}},true);
 function img(url,alt,extra=''){return`<img src="${esc(url)}" alt="${esc(alt)}" loading="lazy" decoding="async" ${extra}>`;}
 function cardTile(card,action='card',thumb=true){const tr=C.canTrain(card),character=C.charName(card.characterId),supply=(C.T.cardSupplies||[]).find(s=>s.id===card.cardSupplyId);const limited=supply&&['term_limited','colorful_festival_limited','bloom_festival_limited','unit_event_limited','collaboration_limited'].includes(supply.cardSupplyType);return`<button type="button" class="card-tile" data-action="${action}" data-id="${card.id}" aria-label="${esc(character+' '+card.prefix)}"><div class="card-picture">${img(C.cardArt(card,tr,thumb),character+' '+card.prefix)}<span class="rarity${card.cardRarityType==='rarity_birthday'?' birthday':''}">${C.rarityLabel(card)}</span><span class="attr-badge attr-${card.attr}" title="${C.attr[card.attr]?.name}">${C.attr[card.attr]?.symbol||''}</span></div><div class="card-caption"><div class="card-character"><span>${esc(character)}</span>${favorites.includes(card.id)?'<span class="favorite-dot">★</span>':''}</div><h3>${esc(card.prefix)}</h3><div class="card-meta-line"><span>${esc(C.unitLabel(card).replace('，Nightcord见。',''))}</span><span class="dot"></span><span>${limited?'限定':'#'+card.id}</span></div></div></button>`;}
 function heading(en,title,desc,actions=''){return`<div class="page-heading"><div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="planner-actions">${actions}</div>`:''}</div>`;}
 function empty(title,desc,action=''){return`<div class="empty-state">${icon('star')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;}
 function renderHome(){
  const latest=C.releasedCards.slice(0,4);const hero=C.cards.get(833)||C.releasedCards.find(c=>c.characterId===17&&C.canTrain(c));
  $('#view-home').innerHTML=`${storageUnavailable?`<div class="notice warning storage-warning">${icon('info')}浏览器未允许本地存储。你仍可使用所有工具，请用 JSON 导出保存培养方案。</div>`:''}<div class="hero"><div class="hero-visual">${img(C.cardArt(hero,true),C.charName(hero.characterId)+'「'+hero.prefix+'」特训后','class="hero-art" fetchpriority="high" loading="eager"')}<span class="hero-tag">${esc(C.charName(hero.characterId)+' / '+hero.prefix)}</span></div><div class="hero-content"><span class="eyebrow">A LITTLE CLOSER TO YOUR SEKAI</span><h1>为下一场 Live，<br>准备<em>更好的自己。</em></h1><p>收藏喜欢的卡面，读懂每一张谱面。<br>从一张卡牌开始，规划属于你的五人队伍。</p><div class="button-row"><a class="button primary" href="#planner">开始养成规划 ${icon('arrow')}</a><a class="button ghost" href="#cards">浏览卡牌</a></div></div><span class="hero-spark" aria-hidden="true">✧</span></div>
  <div class="stat-strip">${[['cards',C.releasedCards.length,'国服已发布卡牌'],['chart',C.releasedMusics.length,'国服已发布乐曲'],['star',C.characters.size,'可选角色'],['calc','1 → 5','单卡与队伍规划']].map(([i,v,label])=>`<div class="stat-cell"><div class="stat-icon">${icon(i)}</div><div><strong>${typeof v==='number'?fmt(v):v}</strong><small>${label}</small></div></div>`).join('')}</div>
  <div class="section-heading"><div><h2>探索你的世界</h2><p class="sub">资料查询、谱面练习与养成规划，在这里连接。</p></div></div><div class="feature-row"><a href="#cards" class="feature-tile">${icon('cards')}${icon('arrow').replace('<svg','<svg class="tile-arrow"')}<h3>每一张卡，都值得珍藏</h3><p>特训前后的完整画面、成员技能与数值，一起收录。</p></a><a href="#charts" class="feature-tile">${icon('chart')}${icon('arrow').replace('<svg','<svg class="tile-arrow"')}<h3>看清每一个节奏</h3><p>静态全谱与动态播放，流速、进度和演唱版本自由调整。</p></a><a href="#planner" class="feature-tile">${icon('calc')}${icon('arrow').replace('<svg','<svg class="tile-arrow"')}<h3>把养成计划算清楚</h3><p>对比综合力变化，汇总材料消耗，记录还差多少道具。</p></a></div>
  <div class="section-heading"><div><h2>最近发布的卡牌</h2><p class="sub">按内置国服资料的发布时间排序</p></div><a href="#cards" class="text-btn">查看全部 ${icon('arrow')}</a></div><div class="card-grid">${latest.map(c=>cardTile(c)).join('')}</div><div class="notice" style="margin-top:22px">${icon('info')}<span>资料版本 CN ${esc(C.D.meta.masterVersion)} · 上游更新 ${esc(C.D.meta.sourceUpdatedAt.slice(0,10))} · 本次收集 ${esc(C.D.meta.snapshotDate)}。仅显示截至收集日已发布的条目；公开镜像可能存在更新延迟。</span></div>`;
 }
 function cardFilterMarkup(){return`<div class="filters"><div class="filter-line"><label class="searchbox">${icon('search')}<input id="card-search" type="search" placeholder="搜索卡名、角色或卡牌 ID" aria-label="搜索卡牌" value="${esc(cardFilters.query)}"></label><select id="card-character" aria-label="筛选角色"><option value="">全部角色</option>${[...C.characters.values()].map(c=>`<option value="${c.id}"${selected(cardFilters.character,c.id)}>${esc(C.charName(c.id))}</option>`).join('')}</select><select id="card-unit" aria-label="筛选组合"><option value="">全部组合</option>${Object.entries(C.units).map(([k,v])=>`<option value="${k}"${selected(cardFilters.unit,k)}>${esc(v)}</option>`).join('')}</select></div><div class="filter-line"><select id="card-attr" aria-label="筛选属性"><option value="">全部属性</option>${Object.entries(C.attr).map(([k,v])=>`<option value="${k}"${selected(cardFilters.attr,k)}>${v.symbol} ${v.name}</option>`).join('')}</select><select id="card-rarity" aria-label="筛选稀有度"><option value="">全部稀有度</option>${[...C.rarities.keys()].map(k=>`<option value="${k}"${selected(cardFilters.rarity,k)}>${k==='rarity_birthday'?'生日卡':k.split('_')[1]+' 星'}</option>`).join('')}</select><select id="card-supply" aria-label="筛选卡牌类型"><option value="">全部卡牌类型</option><option value="limited"${selected(cardFilters.supply,'limited')}>限定卡牌</option><option value="normal"${selected(cardFilters.supply,'normal')}>普通卡牌</option><option value="festival"${selected(cardFilters.supply,'festival')}>Fes 卡牌</option></select><button class="filter-chip ${cardFilters.favorite?'active':''}" data-action="filter-favorite">★ 仅看收藏</button><button class="text-btn" data-action="clear-card-filters">重置</button></div></div>`;}
 function renderCards(){const view=$('#view-cards');view.innerHTML=heading('CARD COLLECTION','卡牌图鉴','每一份闪闪发光的心愿，都有属于它的故事。')+cardFilterMarkup()+'<div id="card-results"></div>';updateCardResults();}
 function updateCardResults(){
  let list=C.filterCards({...cardFilters,favorites});if(cardFilters.supply)list=list.filter(c=>{const type=(C.T.cardSupplies||[]).find(x=>x.id===c.cardSupplyId)?.cardSupplyType||'normal';return cardFilters.supply==='limited'?type.includes('limited'):cardFilters.supply==='festival'?type.includes('festival'):type==='normal';});const size=24,total=Math.max(1,Math.ceil(list.length/size));cardPage=Math.min(cardPage,total);
  $('#card-results').innerHTML=`<div class="results-toolbar"><span>共 <strong>${fmt(list.length)}</strong> 张卡牌${cardFilters.favorite?' · 已收藏':''}</span><select id="card-sort" aria-label="卡牌排序"><option value="new"${selected(cardFilters.sort,'new')}>最近发布</option><option value="old"${selected(cardFilters.sort,'old')}>最早发布</option><option value="power"${selected(cardFilters.sort,'power')}>满配基础综合力</option></select></div>${list.length?`<div class="card-grid">${list.slice((cardPage-1)*size,cardPage*size).map(c=>cardTile(c)).join('')}</div><div class="pagination"><button class="button small" data-action="card-page" data-step="-1"${cardPage===1?' disabled':''}>上一页</button><span>${cardPage} / ${total}</span><button class="button small" data-action="card-page" data-step="1"${cardPage===total?' disabled':''}>下一页</button></div>`:empty('暂时没有找到卡牌','试试更换关键词或减少筛选条件。')}`;
 }
 function showDetail(id,trained){const card=C.cards.get(Number(id));if(!card)return;detail={id:card.id,trained:trained===undefined?C.canTrain(card):!!trained,skillLevel:detail.id===card.id?detail.skillLevel:4,characterRank:detail.id===card.id?detail.characterRank:1};const s=C.maxState(card),v=C.basePowers(card,s),favor=favorites.includes(card.id);const supply=(C.T.cardSupplies||[]).find(x=>x.id===card.cardSupplyId)?.cardSupplyType||'normal',types={normal:'普通',birthday:'生日',term_limited:'期间限定',colorful_festival_limited:'Colorful Fes',bloom_festival_limited:'Bloom Fes',unit_event_limited:'组合活动限定',collaboration_limited:'联动限定'};
  $('#detail-content').innerHTML=`<div class="detail-hero">${img(C.cardArt(card,detail.trained),card.prefix,'loading="eager"')}<button class="icon-btn" data-close="detail-dialog" aria-label="关闭卡牌详情">${icon('close')}</button></div><div class="detail-body"><div class="character-name">${esc(C.charName(card.characterId))} · ${esc(C.unitLabel(card))}</div><h2>${esc(card.prefix)}</h2><div class="pills"><span class="pill">${C.rarityLabel(card)}</span><span class="pill">${C.attr[card.attr]?.name}</span><span class="pill">${esc(types[supply]||supply)}</span><span class="pill">#${card.id}</span><span class="pill">国服 ${date(card.releaseAt)}</span></div><div class="detail-tools"><div class="segmented"><button data-action="art-toggle" data-trained="0" class="${!detail.trained?'active':''}">特训前</button>${C.canTrain(card)?`<button data-action="art-toggle" data-trained="1" class="${detail.trained?'active':''}">特训后</button>`:''}</div><div class="button-row"><button class="button small" data-action="favorite">${icon('star')}${favor?'已收藏':'收藏'}</button><button class="button small" data-action="download-art">${icon('download')}高清卡面</button><button class="button small" data-action="export-card">${icon('download')}资料卡 PNG</button></div></div><div class="detail-grid"><div class="info-panel"><h3>满配基础综合力 <span style="color:var(--mint)">${fmt(v.reduce((a,b)=>a+b,0))}</span></h3><dl class="data-list"><dt>表演 / 技巧 / 耐力</dt><dd>${v.map(fmt).join(' / ')}</dd><dt>最高等级</dt><dd>${C.maxLevel(card,true)}</dd><dt>专家 / 技能等级</dt><dd>5 / 4</dd></dl><p class="mini-note">含特训、专家5、已读双剧情、对应装饰画；区域道具及其他比例加成请在养成规划中设置。</p></div><div class="info-panel"><h3>${esc(card.cardSkillName||'成员技能')}</h3><div style="margin-bottom:9px"><select id="detail-skill-level" aria-label="查看技能等级">${[1,2,3,4].map(i=>`<option value="${i}"${i===detail.skillLevel?' selected':''}>技能等级 ${i}</option>`).join('')}</select></div><p id="skill-description">${esc(C.skillDescription(card,detail.skillLevel,{characterRank:detail.characterRank}))}</p>${card.specialTrainingSkillId?`<div class="section-divider"></div><div class="field"><label for="detail-character-rank">技能参照角色等级</label><input id="detail-character-rank" type="number" min="1" max="${C.rankMax.get(card.characterId)}" value="${detail.characterRank}"></div><h3 style="margin-top:14px">特训追加技能</h3><p id="trained-skill-description">${esc(C.skillDescription(card,detail.skillLevel,{skillId:card.specialTrainingSkillId,characterRank:detail.characterRank}))}</p><p class="mini-note">原始与追加技能分别展示，效果不相加。</p>`:''}</div></div><div class="button-row" style="margin-top:21px"><button class="button primary" data-action="add-team" data-id="${card.id}">${icon('plus')}加入五人队伍</button><button class="button" data-action="add-single" data-id="${card.id}">${icon('calc')}单卡养成计算</button></div><p class="detail-note">卡面显示与特训状态独立。查看特训后插画不会改变你的培养方案。</p></div>`;
  if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
 }
 function updateDetailSkill(){const card=C.cards.get(detail.id);if(!card)return;detail.skillLevel=C.n($('#detail-skill-level')?.value||4,1,4);detail.characterRank=C.n($('#detail-character-rank')?.value||1,1,C.rankMax.get(card.characterId));$('#skill-description').textContent=C.skillDescription(card,detail.skillLevel,{characterRank:detail.characterRank});const extra=$('#trained-skill-description');if(extra)extra.textContent=C.skillDescription(card,detail.skillLevel,{skillId:card.specialTrainingSkillId,characterRank:detail.characterRank});}
 function openPicker(slot){picker={slot:C.n(slot,0,4),page:1,query:'',character:''};$('#picker-filters').innerHTML=`<div class="filter-line"><label class="searchbox">${icon('search')}<input id="picker-search" type="search" placeholder="搜索卡名、角色或 ID" aria-label="搜索可选卡牌"></label><select id="picker-character" aria-label="选择角色"><option value="">全部角色</option>${[...C.characters.values()].map(c=>`<option value="${c.id}">${esc(C.charName(c.id))}</option>`).join('')}</select></div><p class="mini-note" style="margin-top:9px">${mode==='single'?'选择要计算的单张卡牌。':'普通编组为五个不同角色；选择已有角色的新卡会替换该角色的位置。'}</p>`;updatePicker();$('#picker-dialog').showModal();}
 function updatePicker(){const list=C.filterCards({query:picker.query,character:picker.character}),size=20,total=Math.max(1,Math.ceil(list.length/size));picker.page=Math.min(picker.page,total);$('#picker-results').innerHTML=list.length?list.slice((picker.page-1)*size,picker.page*size).map(c=>cardTile(c,'pick-card')).join(''):empty('没有找到卡牌','换一个关键词试试。');let old=$('#picker-pagination');if(!old){old=document.createElement('div');old.id='picker-pagination';$('#picker-dialog').append(old);}old.innerHTML=`<div class="pagination"><button class="button small" data-action="picker-page" data-step="-1"${picker.page===1?' disabled':''}>上一页</button><span>${picker.page} / ${total} · ${list.length} 张</span><button class="button small" data-action="picker-page" data-step="1"${picker.page===total?' disabled':''}>下一页</button></div>`;}
 function insertCard(id,slot,desiredMode=mode){switchMode(desiredMode,false);const card=C.cards.get(Number(id));if(!card)return;let target=desiredMode==='single'?0:C.n(slot,0,4);const existing=plan.slots.findIndex(s=>s&&C.cards.get(s.cardId)?.characterId===card.characterId);if(desiredMode==='team'&&existing>=0)target=existing;plan.slots[target]=C.newSlot(card.id);plan.activeSlot=target;persist();$('#picker-dialog').close();$('#detail-dialog').close();if(location.hash!=='#planner')location.hash='planner';else renderPlanner();toast(`已${existing>=0&&desiredMode==='team'?'替换':'选择'}${C.charName(card.characterId)} · 第 ${target+1} 位`);}
 function switchMode(next,render=true){mode=next==='single'?'single':'team';drafts[plan.mode]=plan;plan=drafts[mode];plan.mode=mode;persist();if(render)renderPlanner();}

 function renderCharts(){if(chartState.player){chartState.player.destroy();chartState.player=null;}$('#view-charts').innerHTML=heading('SCORE STUDIO','谱面研究室','让难点慢下来，让每一次练习更有方向。')+`<div class="chart-layout"><aside class="song-library"><label class="searchbox">${icon('search')}<input id="song-search" type="search" placeholder="歌名、作者或 ID" aria-label="搜索歌曲" value="${esc(chartState.query)}"></label><p class="mini-note" style="padding:8px 2px 0">${fmt(C.releasedMusics.length)} 首国服已发布乐曲</p><div class="song-list" id="song-list"></div></aside><div class="chart-workspace"><div id="song-header"></div><div class="chart-controls"><div class="control-top"><div class="segmented"><button data-action="chart-mode" data-mode="dynamic" class="${chartState.mode==='dynamic'?'active':''}">动态播放</button><button data-action="chart-mode" data-mode="static" class="${chartState.mode==='static'?'active':''}">静态全谱</button></div><div class="button-row"><button class="button small" data-action="reload-chart">重新读取</button><button class="button small" data-action="export-chart">${icon('download')}导出全谱</button></div></div><div class="player-options"><div class="field"><label for="note-speed">音符流速</label><input id="note-speed" type="number" min="1" max="12" step="0.1" value="${chartState.speed}"></div><div class="field"><label for="playback-rate">播放速度</label><select id="playback-rate">${[.25,.5,.75,1,1.25,1.5,2].map(v=>`<option value="${v}"${selected(chartState.rate,v)}>${v}×</option>`).join('')}</select></div><div class="field"><label for="audio-offset">校准偏移 / ms</label><input id="audio-offset" type="number" min="-5000" max="5000" step="10" value="${chartState.offset}"></div><label class="check-field"><input id="silent-preview" type="checkbox"${checked(chartState.silent)}>无声预览</label></div></div><div id="chart-load-status"></div><div id="dynamic-block" class="${chartState.mode==='dynamic'?'':'hidden'}"><div class="chart-stage"><canvas id="player-canvas" aria-label="动态谱面画面"></canvas><div id="stage-overlay" class="stage-overlay">${icon('chart')}<p>正在读取国服谱面…</p></div></div><div class="transport"><button class="play-btn" id="play-toggle" aria-label="播放谱面">${icon('play')}</button><button class="icon-btn small" data-action="restart-player" aria-label="从头播放">${icon('reset')}</button><div class="progress-wrap"><input id="chart-progress" type="range" min="0" max="1" step="0.001" value="0" aria-label="谱面播放进度"><div class="transport-time"><span id="chart-current-time">00:00.000</span><span id="chart-duration">00:00.000</span></div></div></div><div class="audio-status" id="audio-status"></div></div><div id="static-block" class="${chartState.mode==='static'?'':'hidden'}"><div class="static-options"><span>缩放 <output id="static-zoom-value">${chartState.zoom}%</output></span><input id="static-zoom" type="range" min="25" max="250" step="5" value="${chartState.zoom}" aria-label="静态谱面缩放"><label class="check-field"><input id="static-dark" type="checkbox"${checked(chartState.staticDark)}>深色谱面</label></div><div class="static-wrap" id="static-chart-wrap"><div class="loading-inline">读取完成后将在这里显示完整谱面。</div></div></div><div id="chart-metadata" class="chart-metadata"></div><p class="mini-note">动态预览可调整流速、播放速度并拖动进度。空格播放 / 暂停，← / → 跳转 5 秒。静态全谱按列从左至右、每列从上至下阅读。</p></div></div>`;
  updateSongList();renderSongHeader();chartState.player=new CH.Player($('#player-canvas'),{onUpdate:updateTransport,onStatus:(message,state)=>{const el=$('#audio-status');if(el){el.textContent=message;el.style.color=state==='warning'?'var(--gold)':'';}}});loadCurrentChart();}
 function updateSongList(){const q=chartState.query.trim().normalize('NFKC').toLowerCase();const list=C.releasedMusics.filter(m=>!q||`${m.title} ${m.pronunciation||''} ${m.composer} ${m.lyricist} ${m.id}`.normalize('NFKC').toLowerCase().includes(q));$('#song-list').innerHTML=list.slice(0,chartState.limit).map(m=>`<button class="song-row ${m.id===chartState.songId?'selected':''}" data-action="song" data-id="${m.id}">${img(C.jacket(m),m.title)}<span><strong>${esc(m.title)}</strong><small>#${m.id} · ${esc(m.composer||'—')}</small></span></button>`).join('')+(list.length>chartState.limit?`<button class="song-more" data-action="more-songs">加载更多 · 还有 ${list.length-chartState.limit} 首</button>`:'')+(!list.length?'<p class="mini-note" style="padding:15px">没有找到歌曲。</p>':'');}
 function currentDifficulty(){return(C.T.musicDifficulties||[]).find(d=>d.musicId===chartState.songId&&d.musicDifficulty===chartState.difficulty);}
 function currentVocal(){const list=C.vocalList(chartState.songId);return list.find(v=>v.id===chartState.vocalId)||list.find(v=>v.musicVocalType==='sekai')||list[0];}
 function renderSongHeader(){const m=C.musics.get(chartState.songId)||C.releasedMusics[0];chartState.songId=m.id;const diffs=(C.T.musicDifficulties||[]).filter(d=>d.musicId===m.id&&(!d.publishedAt||d.publishedAt<=Math.min(Date.now(),C.D.meta.releaseCutoff)));if(!diffs.some(d=>d.musicDifficulty===chartState.difficulty))chartState.difficulty=diffs.find(d=>d.musicDifficulty==='expert')?.musicDifficulty||diffs[0]?.musicDifficulty||'expert';const vocals=C.vocalList(m.id).filter(v=>!v.archivePublishedAt||v.archivePublishedAt<=C.D.meta.releaseCutoff);const vocal=currentVocal();chartState.vocalId=vocal?.id;
  $('#song-header').innerHTML=`<div class="song-header">${img(C.jacket(m),m.title)}<div class="song-header-content"><span class="eyebrow" style="font-size:8px;margin-bottom:5px">MUSIC #${m.id}</span><h2>${esc(m.title)}</h2><p class="song-credit">作词 ${esc(m.lyricist||'—')} · 作曲 ${esc(m.composer||'—')}</p><div class="difficulty-row">${Object.keys(C.diff).map(k=>diffs.find(d=>d.musicDifficulty===k)).filter(Boolean).map(d=>`<button class="diff-btn ${d.musicDifficulty===chartState.difficulty?'active':''}" style="--diff-color:${C.diff[d.musicDifficulty]?.color}" data-action="difficulty" data-difficulty="${d.musicDifficulty}">${C.diff[d.musicDifficulty]?.name} <strong>${d.playLevel}</strong></button>`).join('')}</div></div></div><div class="field" style="margin-bottom:16px"><label for="vocal-select">演唱版本</label><select id="vocal-select">${vocals.map(v=>`<option value="${v.id}"${selected(chartState.vocalId,v.id)}>${esc(v.caption||v.musicVocalType)}${v.characters?.length?' · '+v.characters.map(c=>C.charName(c.characterId)).join(' / '):''}</option>`).join('')}</select></div>`;
 }
 async function loadCurrentChart(){const token=++chartState.token;chartState.controller?.abort();chartState.controller=new AbortController();chartState.player?.pause();chartState.loaded=null;chartState.staticCanvas=null;const overlay=$('#stage-overlay');if(overlay){overlay.classList.remove('hidden');overlay.innerHTML=icon('chart')+'<p>正在读取国服谱面…</p>';}$('#chart-load-status').innerHTML='';$('#static-chart-wrap').innerHTML='<div class="loading-inline">正在读取谱面…</div>';
  try{const chart=await CH.fetchChart(chartState.songId,chartState.difficulty,{signal:chartState.controller.signal});if(token!==chartState.token||currentView!=='charts')return;chartState.loaded=chart;const music=C.musics.get(chartState.songId),vocal=currentVocal();chartState.player.load(chart,music,vocal?C.audioUrl(vocal):null);chartState.player.setOptions({speed:chartState.speed,rate:chartState.rate,offsetMs:chartState.offset,silent:chartState.silent});$('#stage-overlay').classList.add('hidden');const d=currentDifficulty();$('#chart-metadata').innerHTML=`<span>${esc(chart.source)}</span><span>BPM ${esc(chart.bpms.join(' / '))}</span><span>Lv.${d?.playLevel??'—'}</span><span>物量 ${fmt(d?.totalNoteCount)}</span>`;if(chartState.mode==='static')drawStatic();}
  catch(error){if(token!==chartState.token||currentView!=='charts')return;$('#stage-overlay').innerHTML=icon('info')+`<p>${esc(error.message)}</p><button class="button small" data-action="reload-chart">重试</button>`;$('#static-chart-wrap').innerHTML=empty('谱面暂时无法读取',esc(error.message));$('#chart-load-status').innerHTML=`<div class="notice warning chart-loading">${icon('info')}<span>谱面资源可能尚未同步或网络暂不可用。曲目信息仍可查看；可先试试 Tell Your World 或 ROKI 的 EXP / MAS 内置谱面。</span></div>`;}
 }
 function formatTime(t){const ms=Math.max(0,Math.round(t*1000));return`${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}`;}
 function updateTransport(player){const progress=$('#chart-progress');if(!progress)return;const max=String(Math.max(1,player.duration));if(progress.max!==max)progress.max=max;if(!chartState.seeking)progress.value=String(player.time);const time=$('#chart-current-time'),duration=$('#chart-duration'),timeText=formatTime(player.time),durationText=formatTime(player.duration);if(time.textContent!==timeText)time.textContent=timeText;if(duration.textContent!==durationText)duration.textContent=durationText;const b=$('#play-toggle'),action=player.active?'pause':'play',state=player.pending?'pending':player.playing?'playing':'paused';if(b.dataset.icon!==action){b.innerHTML=icon(action);b.dataset.icon=action;}if(b.dataset.state!==state){b.dataset.state=state;b.setAttribute('aria-label',player.active?'暂停谱面':'播放谱面');b.setAttribute('aria-pressed',String(player.active));b.setAttribute('aria-busy',String(player.pending));b.title=player.pending?'取消等待并暂停':player.active?'暂停谱面':'播放谱面';}}
 function drawStatic(){if(!chartState.loaded)return;const m=C.musics.get(chartState.songId),d=currentDifficulty();const canvas=CH.renderStatic(chartState.loaded,{title:m.title,difficulty:chartState.difficulty,level:d?.playLevel,dark:chartState.staticDark});chartState.staticCanvas=canvas;$('#static-chart-wrap').replaceChildren(canvas);updateStaticZoom();}
 function updateStaticZoom(){const canvas=chartState.staticCanvas;if(!canvas)return;const wrap=$('#static-chart-wrap'),fit=(wrap.clientWidth||600)/canvas.width;canvas.style.width=Math.round(canvas.width*fit*chartState.zoom/100)+'px';canvas.style.height='auto';$('#static-zoom-value').textContent=chartState.zoom+'%';}

 function slotMarkup(slot,i){if(!slot)return`<div class="team-slot"><button class="slot-empty" data-action="slot-picker" data-slot="${i}">${icon('plus')}选择成员<span>MEMBER ${String(i+1).padStart(2,'0')}</span></button></div>`;const c=C.cards.get(slot.cardId);return`<div class="team-slot ${plan.activeSlot===i?'active':''}"><div data-action="slot-select" data-slot="${i}" role="button" tabindex="0" aria-label="编辑${esc(C.charName(c.characterId))}">${img(C.cardArt(c,slot.target.trained,true),c.prefix,'class="slot-art"')}<div class="slot-info"><strong>${esc(C.charName(c.characterId))}</strong><small>Lv.${slot.current.level} → ${slot.target.level} · 专家 ${slot.target.master}</small></div></div><span class="slot-number">${i===0?'LEADER':'MEMBER '+(i+1)}</span><button class="slot-change" data-action="slot-picker" data-slot="${i}">换卡</button></div>`;}
 function numberField(label,value,{id='',min=0,max=999,step=1,attrs=''}={}){return`<div class="field"><label${id?` for="${id}"`:''}>${label}</label><input type="number"${id?` id="${id}"`:''} min="${min}" max="${max}" step="${step}" value="${value}" ${attrs} aria-label="${esc(label)}"></div>`;}
 function stateEditor(slot,side,index){const c=C.cards.get(slot.cardId),s=slot[side],a=slot.current;const base=`data-slot="${index}" data-side="${side}"`;const numfield=(label,field,min,max)=>numberField(label,s[field],{id:`slot-${side}-${field}`,min:side==='target'?Math.max(min,a[field]):min,max,attrs:`data-slot-field="${field}" ${base}`});const check=(field,label,disabled=false)=>`<label class="check-field"><input type="checkbox" data-slot-field="${field}" ${base}${checked(s[field])}${disabled?' disabled':''}>${label}</label>`;const episodes=C.eps.get(c.id)||[];return`<div><div class="state-title ${side==='target'?'target':''}"><span class="state-dot"></span>${side==='current'?'当前培养状态':'目标培养状态'}</div><div class="form-grid">${numfield('卡牌等级','level',1,C.maxLevel(c,s.trained))}${numfield('专家等级','master',0,5)}${numfield('技能等级','skill',1,4)}</div><div class="state-checks">${C.canTrain(c)?check('trained','已完成特训'):''}${episodes.some(e=>e.cardEpisodePartType==='first_part')?check('story1','前篇剧情已阅读'):''}${episodes.some(e=>e.cardEpisodePartType==='second_part')?check('story2','后篇剧情已阅读'):''}${check('canvas','对应装饰画已制作')}</div><p class="state-level-note">${C.rarityLabel(c)} · 等级上限 ${C.maxLevel(c,s.trained)}${C.canTrain(c)?'（随特训状态变化）':''}</p></div>`;}
 let areaScope='relevant',areaCategory='all';
 function areaRows(){let list=areaScope==='all'?C.T.areaItems:C.relevantAreas(plan);return list.filter(a=>{const l=C.areaLevels.get(`${a.id}:1`);return areaCategory==='all'||(areaCategory==='character'?l.targetGameCharacterId!==undefined:areaCategory==='unit'?l.targetUnit!=='any':l.targetCardAttr!=='any');});}
 function areaPanel(){const list=areaRows();return`<details class="disclosure" id="area-options"><summary><span>区域道具 <span class="meta-small">角色 · 组合 · 属性</span></span>${icon('chevron')}</summary><div class="disclosure-body"><div class="field-row"><select id="area-scope" aria-label="区域道具显示范围"><option value="relevant"${selected(areaScope,'relevant')}>仅看与当前队伍有关</option><option value="all"${selected(areaScope,'all')}>显示全部 55 件道具</option></select><select id="area-category" aria-label="区域道具类别"><option value="all"${selected(areaCategory,'all')}>全部类别</option><option value="character"${selected(areaCategory,'character')}>角色道具</option><option value="unit"${selected(areaCategory,'unit')}>组合道具</option><option value="attr"${selected(areaCategory,'attr')}>属性植物</option></select></div><p class="mini-note" style="margin-top:10px">0 表示未购入。组合、属性的全员匹配加成由五张卡牌自动判断；公共道具的升级消耗统一计算一次。</p><div class="field-row" style="margin-top:12px">${numberField('批量当前等级',0,{id:'area-bulk-current',max:20})}${numberField('批量目标等级',10,{id:'area-bulk-target',max:20})}<button class="button small" data-action="bulk-areas">应用到当前显示道具</button></div><div class="table-labels"><span>${list.length} 件道具</span><span>当前等级</span><span></span><span>目标等级</span></div>${list.length?list.map(a=>{const l=C.areaLevels.get(`${a.id}:${plan.areas.target[a.id]||1}`);return`<div class="area-row"><div class="area-name">${esc(a.name)}<small>${esc((l?.sentence||'').replace(/<[^>]*>/g,''))}</small></div><input type="number" min="0" max="${C.areaMax.get(a.id)}" value="${plan.areas.current[a.id]||0}" data-global-group="areas" data-side="current" data-id="${a.id}" aria-label="${esc(a.name)}当前等级"><span class="area-arrow">→</span><input type="number" min="${plan.areas.current[a.id]||0}" max="${C.areaMax.get(a.id)}" value="${plan.areas.target[a.id]||0}" data-global-group="areas" data-side="target" data-id="${a.id}" aria-label="${esc(a.name)}目标等级"></div>`;}).join(''):'<p class="mini-note" style="padding:18px 0">选择卡牌后，会列出有关的区域道具。也可以切换为显示全部道具。</p>'}</div></details>`;}
 function activeCharacters(){return[...new Set(C.activeSlots(plan).filter(Boolean).map(s=>C.cards.get(s.cardId).characterId))];}
 function extraPanel(){const chars=activeCharacters();return`<details class="disclosure" id="extra-options"><summary><span>角色等级与称号</span>${icon('chevron')}</summary><div class="disclosure-body"><p class="mini-note">角色等级是角色任务的成长等级，与单张卡牌的专家等级分开设置。称号综合力按所有已持有称号汇总，无须佩戴。</p><div class="table-labels"><span>角色</span><span>当前</span><span></span><span>目标</span></div>${chars.map(id=>`<div class="rank-row"><span class="area-name">${esc(C.charName(id))}</span><input type="number" min="1" max="${C.rankMax.get(id)}" value="${plan.ranks.current[id]||1}" data-global-group="ranks" data-side="current" data-id="${id}" aria-label="${esc(C.charName(id))}当前角色等级"><span class="area-arrow">→</span><input type="number" min="${plan.ranks.current[id]||1}" max="${C.rankMax.get(id)}" value="${plan.ranks.target[id]||1}" data-global-group="ranks" data-side="target" data-id="${id}" aria-label="${esc(C.charName(id))}目标角色等级"></div>`).join('')}<div class="state-columns" style="margin-top:17px">${numberField('当前称号总加成',plan.honors.current,{max:100000,attrs:'data-honor="current"'})}${numberField('目标称号总加成',plan.honors.target,{min:plan.honors.current,max:100000,attrs:'data-honor="target"'})}</div><p class="mini-note" style="margin-top:12px">角色等级和称号的获得途径不唯一，此处作为已达成条件模拟综合力，不按等级差推算固定材料。</p></div></details>`;}
 function mysekaiPanel(){return`<details class="disclosure" id="mysekai-options"><summary><span>MySEKAI 大门与家具</span>${icon('chevron')}</summary><div class="disclosure-body"><p class="mini-note">对应卡牌的装饰画在单卡状态中设置。这里的大门与家具是另外两类加成；大门升级材料会加入清单。</p><div class="table-labels"><span>大门等级</span><span>当前</span><span></span><span>目标</span></div>${(C.T.mysekaiGates||[]).map(g=>`<div class="area-row"><div class="area-name">${esc(C.units[g.unit]||g.name)}<small>${esc(g.name)}</small></div><input type="number" min="0" max="${C.gateMax.get(g.id)}" value="${plan.gates.current[g.id]||0}" data-global-group="gates" data-side="current" data-id="${g.id}" aria-label="${esc(g.name)}当前等级"><span class="area-arrow">→</span><input type="number" min="${plan.gates.current[g.id]||0}" max="${C.gateMax.get(g.id)}" value="${plan.gates.target[g.id]||0}" data-global-group="gates" data-side="target" data-id="${g.id}" aria-label="${esc(g.name)}目标等级"></div>`).join('')}<div class="section-divider"></div><p class="mini-note">玩偶等家具已取得的角色加成（百分比）。按游戏内合计值填写，上限 ${(C.fixtureCap/10).toFixed(1)}%。手动百分比只用于综合力模拟，不包含家具制作消耗。</p><div class="table-labels"><span>家具加成 / %</span><span>当前</span><span></span><span>目标</span></div>${activeCharacters().map(id=>`<div class="rank-row"><span class="area-name">${esc(C.charName(id))}</span><input type="number" min="0" max="${C.fixtureCap/10}" step="0.1" value="${(plan.fixtures.current[id]||0)/10}" data-global-group="fixtures" data-side="current" data-id="${id}" aria-label="${esc(C.charName(id))}当前家具加成百分比"><span class="area-arrow">→</span><input type="number" min="${(plan.fixtures.current[id]||0)/10}" max="${C.fixtureCap/10}" step="0.1" value="${(plan.fixtures.target[id]||0)/10}" data-global-group="fixtures" data-side="target" data-id="${id}" aria-label="${esc(C.charName(id))}目标家具加成百分比"></div>`).join('')}</div></details>`;}
 function resourcePolicy(){const p=plan.policy;return`<details class="disclosure" id="payment-options"><summary><span>养成支付方式</span>${icon('chevron')}</summary><div class="disclosure-body"><div class="form-grid resource-policy"><div class="field"><label>卡牌经验用乐谱</label><select data-policy="practiceTicket">${C.T.practiceTickets.filter(t=>[1,2,3].includes(t.id)).map(t=>`<option value="${t.id}"${selected(p.practiceTicket,t.id)}>${esc(t.name)} · ${fmt(t.exp)} EXP</option>`).join('')}</select></div><div class="field"><label>专家训练优先支付</label><select data-policy="masterPayment"><option value="fragment"${selected(p.masterPayment,'fragment')}>心愿碎片</option><option value="crystal"${selected(p.masterPayment,'crystal')}>心愿结晶（可用稀有度）</option></select></div><div class="field"><label>技能经验支付</label><select data-policy="skillPayment"><option value="ticket"${selected(p.skillPayment,'ticket')}>技能升级乐谱</option><option value="fragment"${selected(p.skillPayment,'fragment')}>心愿碎片</option></select></div><div class="field"><label>技能升级乐谱规格</label><select data-policy="skillTicket">${C.T.skillPracticeTickets.filter(t=>[1,2,3,4].includes(t.id)).map(t=>`<option value="${t.id}"${selected(p.skillTicket,t.id)}>${esc(t.name)} · ${fmt(t.exp)} EXP</option>`).join('')}</select></div><div class="field" style="grid-column:1/-1"><label>新制作装饰画的配方</label><select data-policy="canvasRecipe">${C.T.canvasRecipes.map(r=>`<option value="${r.blueprintId}"${selected(p.canvasRecipe,r.blueprintId)}>${esc(r.name)}</option>`).join('')}</select></div></div><p class="mini-note" style="margin-top:13px">按当前等级起点到目标等级计算经验，每张卡按所选乐谱向上取整，溢出经验会单列。专家训练的可替代材料只选一种支付；库存缺口按选定的支付方案计算。</p></div></details>`;}
 function renderPlanner(){
  if(currentView==='planner')openDisclosures=new Set($$('details.disclosure[open]',$('#view-planner')).map(x=>x.id));if(!C.activeSlots(plan)[plan.activeSlot]){const next=C.activeSlots(plan).findIndex(Boolean);plan.activeSlot=next<0?0:next;}
  const slots=C.activeSlots(plan),active=slots[plan.activeSlot];
  $('#view-planner').innerHTML=heading('GROWTH PLANNER','养成规划','把当前状态与目标放在一起，算清每一步的提升与消耗。',`<button class="button small" data-action="import-plan">${icon('upload')}导入 JSON</button><button class="button small" data-action="export-json">${icon('download')}导出 JSON</button><button class="button primary small" data-action="save-plan">${icon('save')}保存方案</button>`)+`<div class="team-toolbar"><div class="segmented"><button class="${mode==='team'?'active':''}" data-action="planner-mode" data-mode="team">五人队伍</button><button class="${mode==='single'?'active':''}" data-action="planner-mode" data-mode="single">单张卡牌</button></div><div class="button-row"><span class="mini-note">${esc(plan.name)}</span><button class="text-btn" data-action="sample-plan">载入25时示例</button></div></div><div class="team-slots ${mode==='single'?'single':''}">${slots.map(slotMarkup).join('')}</div><div class="planner-layout"><div class="planner-main">${active?`<div class="panel"><div class="panel-heading"><div class="selected-member-title">${img(C.cardArt(active.cardId,active.target.trained,true),'所选卡牌')}<div><h3>${esc(C.charName(C.cards.get(active.cardId).characterId))}</h3><small>${esc(C.cards.get(active.cardId).prefix)}</small></div></div><div class="button-row"><button class="text-btn" data-action="target-copy">复制当前</button><button class="text-btn" data-action="target-max">目标满配</button><button class="icon-btn small remove-member" data-action="remove-member" aria-label="移除此成员">${icon('trash')}</button></div></div><div class="state-columns">${stateEditor(active,'current',plan.activeSlot)}${stateEditor(active,'target',plan.activeSlot)}</div></div>`:empty('从喜欢的成员开始','选择一张卡牌，即可设置当前与目标培养状态。',`<button class="button primary" data-action="slot-picker" data-slot="0">${icon('plus')}选择卡牌</button>`)}${areaPanel()}${extraPanel()}${mysekaiPanel()}${resourcePolicy()}<div id="plan-messages"></div><div class="panel" id="resource-panel"><div class="panel-heading"><div><h3>材料消耗与库存</h3><small id="resource-count"></small></div><button class="text-btn" data-action="clear-inventory">清空库存</button></div><div id="resource-content"></div></div></div><aside class="planner-summary"><div id="power-summary" class="panel summary-panel"></div></aside></div>`;
  for(const id of openDisclosures){const d=$('#'+id);if(d)d.open=true;}
  renderResults();
 }
 function renderResults(inventoryOnly=false){lastResult=C.calculate(plan);const r=lastResult,values=[['基础数值','base','#b9a4ff'],['区域道具','area','#8acde2'],['角色等级','character','#81e3cf'],['家具加成','fixture','#d9c589'],['大门加成','gate','#b697d8'],['称号加成','honor','#e6a3bd']];
  $('#power-summary').innerHTML=`<div class="panel-heading"><h3>目标综合力</h3><span class="pill">${mode==='team'?'队伍':'单卡'}</span></div><div class="power-total">${r.valid?fmt(r.target.total):'待修正'}</div><div class="power-caption">当前 ${fmt(r.current.total)}<strong>+${fmt(r.target.total-r.current.total)}</strong></div><div class="power-bar">${values.map(([,k,color])=>`<span style="width:${r.target.total?100*r.target[k]/r.target.total:0}%;background:${color}"></span>`).join('')}</div>${values.map(([label,k,color])=>`<div class="power-detail"><span><i style="background:${color}"></i>${label}</span><strong>${fmt(r.target[k])}</strong></div>`).join('')}<div class="power-by-card">${r.target.cards.map(c=>`<div class="power-detail"><span>${esc(C.charName(C.cards.get(c.cardId).characterId))}</span><strong>${fmt(c.total)}</strong></div>`).join('')}</div><button class="button primary" data-action="export-report"${!r.target.cards.length||!r.valid?' disabled':''}>${icon('download')}导出精美报告</button><p class="mini-note" style="margin-top:13px">${mode==='single'?'单卡按未组成完整同团／同属性五人队伍计算区域加成。':'组合、属性全员匹配与虚拟歌手的应援组合自动计算。'}</p>`;
  $('#plan-messages').innerHTML=(r.errors.length?`<div class="notice error" style="margin-bottom:17px">${icon('info')}<span>${r.errors.map(esc).join('<br>')}</span></div>`:'')+(r.warnings.length?`<div class="notice" style="margin-bottom:17px">${icon('info')}<span>${r.warnings.map(esc).join('<br>')}</span></div>`:'');
  $('#resource-count').textContent=`${r.resources.length} 种道具 · ${r.resources.filter(x=>x.shortage>0).length} 种仍有缺口`;
  if(inventoryOnly){for(const row of r.resources){const el=$(`#shortage-${row.type}-${row.id}`);if(el){el.textContent=row.shortage?fmt(row.shortage):'充足';el.className=row.shortage?'shortage':'enough';}}return;}
  $('#resource-content').innerHTML=r.resources.length?`<div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>道具 / 用途</th><th>所需数量</th><th>已持有</th><th>尚缺</th></tr></thead><tbody>${r.resources.map(row=>`<tr><td><div class="resource-name"><span class="resource-icon">${row.type==='coin'?'¥':row.type==='practice_ticket'||row.type==='skill_practice_ticket'?'♪':row.type==='mysekai_material'?'♧':'◇'}</span><span>${esc(row.name)}<span class="resource-source" style="display:block" title="${esc(row.sources.join(' · '))}">${esc(row.sources.join(' · '))}</span></span></div></td><td>${fmt(row.quantity)}</td><td><input type="number" min="0" max="1000000000000" step="1" value="${row.owned}" data-inventory="${esc(row.key)}" aria-label="${esc(row.name)}已持有数量"></td><td id="shortage-${row.type}-${row.id}" class="${row.shortage?'shortage':'enough'}">${row.shortage?fmt(row.shortage):'充足'}</td></tr>`).join('')}</tbody></table></div>${r.xp.length?`<div class="section-divider"></div><p class="mini-note">${r.xp.map(x=>`${esc(C.charName(C.cards.get(x.cardId).characterId))} · ${x.type==='card'?'练习':'技能'}需 ${fmt(x.required)} EXP${x.overflow?'，乐谱溢出 '+fmt(x.overflow):''}`).join('<br>')}</p>`:''}`:'<p class="mini-note">当前与目标之间还没有额外消耗。选定卡牌、提高目标培养状态或区域道具等级后，这里会列出所需材料。</p>';
 }
 function changeSlot(input){const index=C.n(input.dataset.slot,0,4),slot=plan.slots[index];if(!slot)return;const side=input.dataset.side,field=input.dataset.slotField,c=C.cards.get(slot.cardId),s=slot[side];let value=input.type==='checkbox'?input.checked:C.n(input.value,field==='level'||field==='skill'?1:0,field==='level'?C.maxLevel(c,s.trained):field==='master'?5:4);
  if(side==='target'){if(typeof value==='boolean'&&slot.current[field])value=true;else if(typeof value==='number')value=Math.max(value,slot.current[field]);}
  s[field]=value;if(field==='trained'){s.level=Math.min(s.level,C.maxLevel(c,s.trained));if(side==='current'&&value)slot.target.trained=true;}
  if(side==='current'){if(typeof value==='boolean'&&value)slot.target[field]=true;else if(typeof value==='number')slot.target[field]=Math.max(value,slot.target[field]);}
  persist();syncSlotControls(slot,index);renderResults();
 }
 function syncSlotControls(slot,index){const card=C.cards.get(slot.cardId);for(const el of $$(`[data-slot="${index}"][data-slot-field]`)){const side=el.dataset.side,field=el.dataset.slotField,value=slot[side][field];if(el.type==='checkbox')el.checked=!!value;else{if(field==='level')el.max=C.maxLevel(card,slot[side].trained);if(side==='target')el.min=slot.current[field];if(el!==document.activeElement)el.value=value;}}const small=$$('.team-slot .slot-info small')[index];if(small)small.textContent=`Lv.${slot.current.level} → ${slot.target.level} · 专家 ${slot.target.master}`;const notes=$$('.state-level-note');notes.forEach((el,i)=>{const s=slot[i===0?'current':'target'];el.textContent=`${C.rarityLabel(card)} · 等级上限 ${C.maxLevel(card,s.trained)}${C.canTrain(card)?'（随特训状态变化）':''}`;});}
 function changeGlobal(input){const g=input.dataset.globalGroup,id=C.n(input.dataset.id),side=input.dataset.side;const max=g==='areas'?C.areaMax.get(id):g==='gates'?C.gateMax.get(id):g==='ranks'?C.rankMax.get(id):C.fixtureCap;const value=C.n(g==='fixtures'?Number(input.value)*10:input.value,g==='ranks'?1:0,max);plan[g][side][id]=side==='target'?Math.max(value,plan[g].current[id]||(g==='ranks'?1:0)):value;if(side==='current')plan[g].target[id]=Math.max(value,plan[g].target[id]||0);for(const el of $$(`[data-global-group="${g}"][data-id="${id}"]`)){const k=el.dataset.side;if(el!==document.activeElement)el.value=(plan[g][k][id]||(g==='ranks'?1:0))/(g==='fixtures'?10:1);if(k==='target')el.min=(plan[g].current[id]||(g==='ranks'?1:0))/(g==='fixtures'?10:1);}persist();renderResults();}
 function loadSample(){
  const next=C.emptyPlan();next.mode=mode;next.name=mode==='team'?'25时 · 示例养成方案':'奏 · 示例单卡方案';const ids=mode==='single'?[17]:[17,18,19,20,21];next.slots=ids.map(id=>{const c=C.releasedCards.find(c=>c.characterId===id&&c.cardRarityType==='rarity_4'&&c.attr==='happy'&&(id!==21||c.supportUnit==='school_refusal'))||C.releasedCards.find(c=>c.characterId===id&&C.canTrain(c)&&(id!==21||c.supportUnit==='school_refusal'));const s=C.newSlot(c.id);s.current={...C.newState(c),level:C.maxLevel(c,true),trained:C.canTrain(c),story1:true,story2:true};s.target=C.maxState(c);next.ranks.current[id]=20;next.ranks.target[id]=30;return s;});while(next.slots.length<5)next.slots.push(null);for(const a of C.relevantAreas(next)){next.areas.current[a.id]=10;next.areas.target[a.id]=15;}next.inventory=C.clone(plan.inventory);drafts[mode]=next;plan=next;persist();renderPlanner();toast('已载入可编辑的示例方案，所有数值来自国服资料。');
 }

 function renderSaved(){
  $('#view-saved').innerHTML=heading('YOUR COLLECTION','我的方案','把喜欢的编队与养成目标，留在下一次打开的时候。',`<button class="button small" data-action="import-plan">${icon('upload')}导入 JSON</button><button class="button small" data-action="export-backup">${icon('download')}导出全部方案</button>`)+(saved.length?`<div class="saved-grid">${saved.map(item=>{let p;try{p=C.sanitizePlan(item.plan);}catch(_){return'';}const cards=C.activeSlots(p).filter(Boolean),r=C.calculate(p);return`<article class="saved-card"><h3>${esc(item.name)}</h3><p class="saved-date">${esc(new Date(item.updatedAt).toLocaleString('zh-CN'))} · ${p.mode==='single'?'单卡':'五人队伍'}</p><div class="saved-members">${cards.map(s=>img(C.cardArt(s.cardId,s.target.trained,true),C.charName(C.cards.get(s.cardId).characterId))).join('')}</div><p class="saved-count">目标综合力 <strong style="color:var(--mint)">${fmt(r.target.total)}</strong> · ${r.resources.length} 种材料</p><div class="saved-actions"><button class="button primary small" data-action="load-saved" data-id="${esc(item.id)}">继续编辑</button><button class="button small" data-action="export-saved" data-id="${esc(item.id)}">导出 JSON</button><button class="icon-btn small" data-action="delete-saved" data-id="${esc(item.id)}" aria-label="删除${esc(item.name)}">${icon('trash')}</button></div></article>`;}).join('')}</div>`:empty('还没有保存的方案','在养成规划中设置队伍，点击“保存方案”即可收藏。',`<a class="button primary" href="#planner">${icon('calc')}开始规划</a>`))+`<div class="notice" style="margin-top:22px">${icon('info')}<span>方案保存在当前浏览器，包含培养设置和保存时的库存快照。跨设备或清理浏览器数据前，请导出 JSON 备份。</span></div>`;
 }
 function utility(title,body,actions=''){const d=$('#utility-dialog');$('#utility-content').innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button class="icon-btn" data-close="utility-dialog" aria-label="关闭对话框">${icon('close')}</button></div>${body}${actions?`<div class="button-row" style="margin-top:22px">${actions}</div>`:''}`;if(!d.open)d.showModal();}
 function showSave(){utility('保存养成方案',`<p>保存当前卡牌、培养设置、区域道具和库存快照。每次保存会新增一个方案。</p><div class="field"><label for="save-name">方案名称</label><input id="save-name" type="text" maxlength="80" value="${esc(plan.name)}"></div>`,`<button class="button primary" data-action="confirm-save">${icon('save')}保存为新方案</button>`);setTimeout(()=>$('#save-name')?.select(),30);}
 function exportJSON(p,name){const payload={...C.clone(p),exportedAt:new Date().toISOString(),dataVersion:C.D.meta.masterVersion};E.downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),cleanName(name||p.name)+'.json');}
 function about(){utility('关于 Yoisaki',`<p>国服 PJSK 卡牌图鉴、谱面研究室与手动养成规划工具。输入的编队和库存保存在你的浏览器。</p><h3>资料版本</h3><dl class="data-list"><dt>服务器</dt><dd>中国大陆 · CN</dd><dt>主数据版本</dt><dd>${esc(C.D.meta.masterVersion)}</dd><dt>上游更新日期</dt><dd>${esc(C.D.meta.sourceUpdatedAt.slice(0,10))}</dd><dt>本次收集日期</dt><dd>${esc(C.D.meta.snapshotDate)}</dd><dt>已发布卡牌 / 歌曲</dt><dd>${fmt(C.releasedCards.length)} / ${fmt(C.releasedMusics.length)}</dd></dl><p>资料为可复现的公开快照，可能落后于游戏。只展示收集日之前已发布的条目，暂不将未来卡牌显示为国服已实装。</p><h3>计算范围</h3><p>支持逐级卡牌数值、特训、专家等级、双剧情、装饰画、区域道具、角色等级、称号、大门及手动家具加成。技能等级改变技能和养成成本，不直接增加固定综合力。材料按当前等级起点计算，角色等级／称号／手动家具加成不推算固定消耗。</p><h3>资源与权属</h3><p>国服主数据来自 <a href="${esc(C.D.meta.sourceUrl)}" target="_blank" rel="noopener noreferrer">Sekai-World 公开资料</a>，媒体资源来自公开国服镜像。SUS 解析器源自 <a href="https://github.com/watagashi-uni/Uni-PJSK-Viewer-Frontend" target="_blank" rel="noopener noreferrer">Uni PJSK Viewer</a>；完整说明见项目文档。</p><p>程序采用 GPL-3.0。卡面、音频、曲绘及谱面的版权属于 SEGA、Colorful Palette、Crypton 及相应权利人。</p><p class="mini-note">两首音源与六张真实谱面作为内置体验；所有媒体优先读取项目内下载的资源。未下载的条目可在线回退，也可在资源设置中切换为仅使用本地资源。</p>`);}
 function settings(){utility('资源设置',`<p>图片、音频与谱面优先读取项目内资源，缺失时使用内置样本或在线镜像。可运行 <code>python scripts/download_assets.py</code> 批量下载。</p><div class="field"><label class="check-field" for="local-only"><input id="local-only" type="checkbox"${checked(C.config.allowOnline===false)}> 仅使用本地资源（不访问在线镜像）</label><small>本地目录：assets/offline/。勾选后，未下载的图片显示占位图，未下载的音频可使用无声预览。</small></div><div class="field"><label for="asset-root">在线回退的国服资源根地址</label><input id="asset-root" type="text" value="${esc(C.config.assetRoot)}"><small>须提供允许浏览器跨域访问的 HTTPS 国服素材镜像。路径结构与离线下载方法见 README。</small></div><p class="mini-note">下载新资源后刷新网页即可使用。更换设置会清除本次访问的资源失败记录。</p>`,`<button class="button primary" data-action="save-settings">保存设置</button><button class="button" data-action="default-settings">恢复默认镜像</button>`);}
 let exportState={kind:'plan',canvas:null,url:null};
 function showExport(kind='plan'){if(kind==='plan'&&(!lastResult?.valid||!lastResult.target.cards.length)){toast('请先完成有效的养成方案。',true);return;}if(exportState.url)URL.revokeObjectURL(exportState.url);exportState={kind,canvas:null,url:null};utility(kind==='card'?'导出卡牌资料卡':'导出养成报告',`<p>选择配色，生成高清 PNG。${kind==='plan'?'报告包含当前 → 目标综合力、成员培养设置与材料缺口。':'资料卡包含高清卡面、满配基础数值与技能说明。'}</p><div class="field"><label for="export-theme">图片配色</label><select id="export-theme"><option value="night">夜间紫 · Nightcord</option><option value="paper">浅色纸张 · Paper</option><option value="mint">薄荷绿 · Mint</option></select></div>${kind==='plan'?'<label class="check-field" style="margin-top:17px"><input id="export-materials" type="checkbox" checked>在报告中包含完整材料清单</label>':''}<div id="export-preview-container"></div>`,`<button class="button primary" data-action="generate-export">${icon('star')}生成预览</button><button id="download-export" class="button" data-action="download-export" disabled>${icon('download')}下载 PNG</button>`);}
 async function generateExport(button){button.disabled=true;const label=button.innerHTML;button.textContent='正在排版与载入卡面…';try{const theme=$('#export-theme').value;const canvas=exportState.kind==='card'?await E.cardReport(C.cards.get(detail.id),{trained:detail.trained,theme}):await E.report(plan,C.calculate(plan),{theme,includeMaterials:$('#export-materials')?.checked});exportState.canvas=canvas;if(exportState.url)URL.revokeObjectURL(exportState.url);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('图片生成失败');exportState.url=URL.createObjectURL(blob);const preview=document.createElement('img');preview.src=exportState.url;preview.alt='导出图片预览';preview.className='export-preview';$('#export-preview-container').replaceChildren(preview);$('#download-export').disabled=false;toast(`已生成 ${canvas.width} × ${canvas.height} 高清图片。`);}catch(e){toast(e.message||'导出失败，请重试。',true);}finally{button.disabled=false;button.innerHTML=label;}}
 async function importFile(file){if(!file)return;if(file.size>10*1024*1024){toast('方案文件请小于 10 MB。',true);return;}try{const input=JSON.parse(await file.text());if(input.schema==='yoisaki-backup'&&input.version===1){if(!Array.isArray(input.plans)||input.plans.length>100)throw new Error('备份最多包含100个方案');const batch=input.plans.map(x=>({id:crypto.randomUUID(),name:String(x.name||'导入方案').slice(0,80),updatedAt:new Date().toISOString(),plan:C.sanitizePlan(x.plan)}));saved=[...batch,...saved].slice(0,100);C.writeStorage('yoisaki-saved',saved);renderSaved();location.hash='saved';toast(`已导入 ${batch.length} 个方案，现有方案保持保留。`);}else{const next=C.sanitizePlan(input);C.writeStorage('yoisaki-before-import',plan);mode=next.mode;drafts[mode]=next;plan=next;persist();location.hash='planner';if(currentView==='planner')renderPlanner();toast('方案与库存快照已导入。');}}catch(e){toast('无法导入：'+e.message,true);}finally{$('#import-file').value='';}}

 document.addEventListener('click',async event=>{
  const close=event.target.closest('[data-close]');if(close){$('#'+close.dataset.close)?.close();return;}
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;
  try{
   switch(action){
    case'card':showDetail(Number(button.dataset.id));break;
    case'art-toggle':showDetail(detail.id,button.dataset.trained==='1');break;
    case'favorite':{const i=favorites.indexOf(detail.id);if(i<0)favorites.push(detail.id);else favorites.splice(i,1);C.writeStorage('yoisaki-favorites',favorites);showDetail(detail.id,detail.trained);if(currentView==='cards')updateCardResults();break;}
    case'filter-favorite':cardFilters.favorite=!cardFilters.favorite;cardPage=1;renderCards();break;
    case'clear-card-filters':cardFilters={query:'',character:'',unit:'',attr:'',rarity:'',favorite:false,sort:'new',supply:''};cardPage=1;renderCards();break;
    case'card-page':cardPage=Math.max(1,cardPage+Number(button.dataset.step));updateCardResults();$('#view-cards').scrollIntoView({block:'start',behavior:'smooth'});break;
    case'picker-page':picker.page=Math.max(1,picker.page+Number(button.dataset.step));updatePicker();$('#picker-dialog').scrollTop=0;break;
    case'pick-card':insertCard(Number(button.dataset.id),picker.slot);break;
    case'add-team':{const team=drafts.team;let i=team.slots.findIndex(s=>!s);if(i<0)i=team.activeSlot||0;insertCard(Number(button.dataset.id),i,'team');break;}
    case'add-single':insertCard(Number(button.dataset.id),0,'single');break;
    case'download-art':{button.disabled=true;const c=C.cards.get(detail.id);try{await E.downloadImage(C.cardArt(c,detail.trained),`Yoisaki-${c.id}-${detail.trained?'trained':'normal'}.webp`);toast('高清卡面已下载。');}finally{button.disabled=false;}break;}
    case'export-card':showExport('card');break;
    case'slot-picker':openPicker(button.dataset.slot);break;
    case'slot-select':plan.activeSlot=Number(button.dataset.slot);persist();renderPlanner();break;
    case'planner-mode':switchMode(button.dataset.mode);break;
    case'target-copy':if(plan.slots[plan.activeSlot]){plan.slots[plan.activeSlot].target=C.clone(plan.slots[plan.activeSlot].current);persist();renderPlanner();}break;
    case'target-max':if(plan.slots[plan.activeSlot]){plan.slots[plan.activeSlot].target=C.maxState(C.cards.get(plan.slots[plan.activeSlot].cardId));persist();renderPlanner();}break;
    case'remove-member':plan.slots[plan.activeSlot]=null;persist();renderPlanner();break;
    case'sample-plan':if(C.activeSlots(plan).some(Boolean)){utility('载入示例方案',`<p>这会替换当前${mode==='single'?'单卡':'五人队伍'}草稿。已保存的方案不受影响。</p>`,`<button class="button primary" data-action="confirm-sample">载入示例</button><button class="button" data-action="save-plan">先保存当前方案</button>`);}else loadSample();break;
    case'confirm-sample':C.writeStorage('yoisaki-before-sample',plan);$('#utility-dialog').close();loadSample();break;
    case'bulk-areas':{const a=C.n($('#area-bulk-current').value,0,20),b=Math.max(a,C.n($('#area-bulk-target').value,0,20));for(const item of areaRows()){plan.areas.current[item.id]=Math.min(a,C.areaMax.get(item.id));plan.areas.target[item.id]=Math.min(b,C.areaMax.get(item.id));}persist();renderPlanner();toast('已应用到当前显示的区域道具。');break;}
    case'clear-inventory':utility('清空库存',`<p>只清空当前草稿中的材料库存，卡牌和培养目标保持保留。已保存的方案不受影响。</p>`,`<button class="button danger" data-action="confirm-clear-inventory">清空当前库存</button><button class="button" data-close="utility-dialog">取消</button>`);break;
    case'confirm-clear-inventory':plan.inventory={};persist();$('#utility-dialog').close();renderResults();toast('当前草稿的库存已清空。');break;
    case'save-plan':if(!C.activeSlots(plan).some(Boolean)){toast('先选择一张卡牌再保存。',true);break;}showSave();break;
    case'confirm-save':{const name=$('#save-name').value.trim()||'我的养成方案';plan.name=name;const record={id:crypto.randomUUID?crypto.randomUUID():`plan-${Date.now()}`,name,updatedAt:new Date().toISOString(),plan:C.clone(plan)};saved.unshift(record);saved=saved.slice(0,100);if(!C.writeStorage('yoisaki-saved',saved))throw new Error('浏览器存储空间不足，请导出 JSON 保存。');persist();$('#utility-dialog').close();if(currentView==='planner')renderPlanner();else renderSaved();toast('方案已保存。');break;}
    case'export-json':exportJSON(plan);break;
    case'import-plan':$('#import-file').click();break;
    case'export-backup':E.downloadBlob(new Blob([JSON.stringify({schema:'yoisaki-backup',version:1,exportedAt:new Date().toISOString(),plans:saved},null,2)],{type:'application/json'}),`Yoisaki-方案备份-${new Date().toISOString().slice(0,10)}.json`);break;
    case'load-saved':{const item=saved.find(x=>x.id===button.dataset.id);if(!item)break;const next=C.sanitizePlan(item.plan);mode=next.mode;plan=next;drafts[mode]=plan;persist();location.hash='planner';toast('方案与保存时的库存已加载。');break;}
    case'export-saved':{const item=saved.find(x=>x.id===button.dataset.id);if(item)exportJSON(C.sanitizePlan(item.plan),item.name);break;}
    case'delete-saved':{const item=saved.find(x=>x.id===button.dataset.id);if(item)utility('删除已保存方案',`<p>删除「${esc(item.name)}」？当前正在编辑的草稿不受影响。</p>`,`<button class="button danger" data-action="confirm-delete" data-id="${esc(item.id)}">删除此方案</button><button class="button" data-close="utility-dialog">取消</button>`);break;}
    case'confirm-delete':saved=saved.filter(x=>x.id!==button.dataset.id);C.writeStorage('yoisaki-saved',saved);$('#utility-dialog').close();renderSaved();toast('方案已删除。');break;
    case'export-report':showExport('plan');break;
    case'generate-export':await generateExport(button);break;
    case'download-export':if(exportState.canvas)await E.downloadCanvas(exportState.canvas,`Yoisaki-${exportState.kind==='card'?'卡牌-'+detail.id:cleanName(plan.name)}.png`);break;
    case'save-settings':{const raw=$('#asset-root').value.trim().replace(/\/+$/,'');const u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw new Error('请填写不包含账号、查询参数或锚点的 HTTPS 资源根地址。');C.config.assetRoot=raw;C.config.allowOnline=!$('#local-only').checked;C.writeStorage('yoisaki-resource-settings',C.config);window.YoisakiResources.reset();CH.clearCache?.();$('#utility-dialog').close();toast(C.config.allowOnline?'已设置为本地优先，缺失时在线回退。':'已设置为仅使用本地资源。');if(currentView==='home')renderHome();if(currentView==='cards')renderCards();if(currentView==='planner')renderPlanner();if(currentView==='charts'){renderSongHeader();loadCurrentChart();}if($('#detail-dialog').open)showDetail(detail.id,detail.trained);break;}
    case'default-settings':$('#asset-root').value='https://storage.exmeaning.com/sekai-cn-assets';break;
    case'song':chartState.songId=Number(button.dataset.id);chartState.vocalId=null;updateSongList();renderSongHeader();loadCurrentChart();break;
    case'more-songs':chartState.limit+=60;updateSongList();break;
    case'difficulty':chartState.difficulty=button.dataset.difficulty;renderSongHeader();loadCurrentChart();break;
    case'reload-chart':CH.clearCache?.(chartState.songId,chartState.difficulty);loadCurrentChart();break;
    case'chart-mode':chartState.mode=button.dataset.mode;$$('[data-action="chart-mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===chartState.mode));$('#dynamic-block').classList.toggle('hidden',chartState.mode!=='dynamic');$('#static-block').classList.toggle('hidden',chartState.mode!=='static');if(chartState.mode==='static'){chartState.player?.pause();drawStatic();}else chartState.player?.draw();break;
    case'restart-player':if(chartState.loaded){chartState.player.pause();chartState.player.seek(0);}break;
    case'export-chart':{if(!chartState.loaded){toast('请先读取谱面。',true);break;}const music=C.musics.get(chartState.songId),difficulty=currentDifficulty();button.disabled=true;try{const canvas=chartState.staticCanvas||CH.renderStatic(chartState.loaded,{title:music.title,difficulty:chartState.difficulty,level:difficulty?.playLevel,dark:chartState.staticDark});await E.downloadCanvas(canvas,`Yoisaki-谱面-${chartState.songId}-${chartState.difficulty}.png`);toast('完整静态谱面已导出。');}finally{button.disabled=false;}break;}
   }
  }catch(error){toast(error.message||'操作未完成，请重试。',true);}
 });
 let searchTimer=0;
 document.addEventListener('input',event=>{const input=event.target;
  if(input.dataset.inventory){const k=input.dataset.inventory;plan.inventory[k]=C.n(input.value,0,1e12);persist();renderResults(true);return;}
  if(input.type==='number'&&input.value!==''&&Number.isFinite(Number(input.value))){if(input.dataset.slotField){changeSlot(input);return;}if(input.dataset.globalGroup){changeGlobal(input);return;}}
  if(input.id==='detail-character-rank'){updateDetailSkill();return;}
  if(input.id==='card-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{cardFilters.query=input.value;cardPage=1;updateCardResults();},150);}
  if(input.id==='picker-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{picker.query=input.value;picker.page=1;updatePicker();},120);}
  if(input.id==='song-search'){chartState.query=input.value;chartState.limit=45;updateSongList();}
  if(input.id==='note-speed'&&input.value!==''&&Number.isFinite(Number(input.value))){chartState.speed=C.num(input.value,1,12);chartState.player?.setOptions({speed:chartState.speed});}
  if(input.id==='chart-progress'&&chartState.loaded){chartState.seeking=true;chartState.player.seek(Number(input.value));}
  if(input.id==='static-zoom'){chartState.zoom=Number(input.value);updateStaticZoom();}
 });
 document.addEventListener('change',event=>{const input=event.target;
  if(input.dataset.slotField){changeSlot(input);return;}
  if(input.dataset.globalGroup){changeGlobal(input);return;}
  if(input.dataset.honor){const side=input.dataset.honor,v=C.n(input.value,0,100000);plan.honors[side]=side==='target'?Math.max(v,plan.honors.current):v;if(side==='current')plan.honors.target=Math.max(v,plan.honors.target);persist();renderPlanner();return;}
  if(input.dataset.policy){const k=input.dataset.policy;plan.policy[k]=['practiceTicket','skillTicket','canvasRecipe'].includes(k)?Number(input.value):input.value;persist();renderResults();return;}
  const filterKeys={'card-character':'character','card-unit':'unit','card-attr':'attr','card-rarity':'rarity','card-supply':'supply','card-sort':'sort'};if(filterKeys[input.id]){cardFilters[filterKeys[input.id]]=input.value;cardPage=1;updateCardResults();return;}
  switch(input.id){
   case'picker-character':picker.character=input.value;picker.page=1;updatePicker();break;
   case'area-scope':areaScope=input.value;renderPlanner();break;
   case'area-category':areaCategory=input.value;renderPlanner();break;
   case'detail-skill-level':updateDetailSkill();break;
   case'detail-character-rank':updateDetailSkill();break;
   case'note-speed':chartState.speed=C.num(input.value,1,12);input.value=chartState.speed;chartState.player?.setOptions({speed:chartState.speed});break;
   case'playback-rate':chartState.rate=Number(input.value);chartState.player?.setOptions({rate:chartState.rate});break;
   case'audio-offset':chartState.offset=C.num(input.value,-5000,5000);chartState.player?.setOptions({offsetMs:chartState.offset});break;
   case'silent-preview':chartState.silent=input.checked;chartState.player?.setOptions({silent:input.checked});break;
   case'chart-progress':chartState.seeking=false;if(chartState.loaded){chartState.player.seek(Number(input.value));updateTransport(chartState.player);}break;
   case'static-dark':chartState.staticDark=input.checked;chartState.staticCanvas=null;drawStatic();break;
   case'vocal-select':{chartState.vocalId=Number(input.value);const v=currentVocal();if(chartState.loaded&&v)chartState.player.setAudio(C.audioUrl(v));break;}
   case'import-file':importFile(input.files?.[0]);break;
  }
 });
 document.addEventListener('click',event=>{if(event.target.closest('#play-toggle')){if(!chartState.loaded){toast('请等待谱面读取完成。');return;}chartState.player.toggle();}});
 document.addEventListener('keydown',event=>{const target=event.target;if(target.matches('[role="button"][data-action]')&&['Enter',' '].includes(event.key)){event.preventDefault();target.click();return;}if(currentView!=='charts'||!chartState.loaded||$$('dialog[open]').length||target.closest('input,select,textarea,button,a,[contenteditable]'))return;if(event.code==='Space'){event.preventDefault();$('#play-toggle').click();}if(event.code==='ArrowLeft'||event.code==='ArrowRight'){event.preventDefault();chartState.player.seek(chartState.player.currentTime()+(event.code==='ArrowRight'?5:-5));}});
 function updateThemeIcon(){const light=document.documentElement.dataset.theme==='light';$('#theme-toggle').innerHTML=icon(light?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',light?'切换为深色模式':'切换为浅色模式');}
 $('#theme-toggle').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('yoisaki-theme',theme);}catch(_){}updateThemeIcon();});
 $('#about-button').addEventListener('click',about);$('#global-settings').addEventListener('click',settings);
 for(const d of $$('dialog')){d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});}
 function route(){const next=(location.hash.slice(1)||'home').split('?')[0];const view=['home','cards','charts','planner','saved'].includes(next)?next:'home';if(currentView==='charts'&&view!=='charts'){chartState.token++;chartState.controller?.abort();chartState.player?.pause();}currentView=view;$$('.view').forEach(s=>s.classList.toggle('hidden',s.id!=='view-'+view));$$('.main-nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const labels={home:'概览',cards:'卡牌图鉴',charts:'谱面研究室',planner:'养成规划',saved:'我的方案'};$('#page-breadcrumb').textContent=labels[view];document.title=`${labels[view]} · Yoisaki`;if(view==='home')renderHome();if(view==='cards')renderCards();if(view==='charts')renderCharts();if(view==='planner')renderPlanner();if(view==='saved')renderSaved();window.scrollTo({top:0,behavior:'instant'});}
 $('#data-version').textContent=`CN ${C.D.meta.masterVersion} · 数据 ${C.D.meta.sourceUpdatedAt.slice(0,10)}`;$('#data-version').title=`本次收集 ${C.D.meta.snapshotDate}；资料可能落后于游戏。`;
 window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>chartState.player?.pause());updateThemeIcon();route();
 window.YoisakiApp={get plan(){return plan;},get result(){return C.calculate(plan);},get chartState(){return chartState;},route,renderPlanner,toast};
})();
